#include <nlohmann/json.hpp>
#include <cstdint>
#include <cassert>
#include <iostream>

enum class book_id : std::uint64_t;
enum class small_id : std::uint32_t;
enum class neg_id : std::int64_t;

using json = nlohmann::json;

int main()
{
    const book_id large_id{static_cast<book_id>(static_cast<std::uint64_t>(1) << 63)};
    json j = large_id;
    std::cout << j.dump() << "\n";
    assert(j > 0u);
    assert(j.dump() == "9223372036854775808");
    assert(j.is_number_unsigned());

    const book_id max_id{static_cast<book_id>(0xFFFFFFFFFFFFFFFEULL)};
    json jm = max_id;
    std::cout << jm.dump() << "\n";
    assert(jm.is_number_unsigned());
    assert(jm.dump() == "18446744073709551614");

    const book_id zero{static_cast<book_id>(0)};
    json jz = zero;
    assert(jz.is_number_unsigned());
    assert(jz.dump() == "0");

    const small_id s{0xDEADBEEFu};
    json js = s;
    std::cout << js.dump() << "\n";
    assert(js.dump() == "3735928559");

    const neg_id n{-2};
    json jn = n;
    std::cout << jn.dump() << "\n";
    assert(jn.is_number_integer());
    assert(jn.dump() == "-2");

    // roundtrip
    auto back = j.get<book_id>();
    assert(back == large_id);
    std::cout << "OK\n";
