#include <nlohmann/json.hpp>
#include <cstdint>
#include <cassert>
#include <iostream>
enum class book_id : std::uint64_t;
enum class neg_id : std::int64_t;
enum class small_id : std::uint32_t;
using json = nlohmann::json;
int main()
{
    json j = book_id{static_cast<book_id>(static_cast<std::uint64_t>(1) << 63)};
    assert(j.dump() == "9223372036854775808" && j.is_number_unsigned());
    json jm = book_id{static_cast<book_id>(0xFFFFFFFFFFFFFFFEULL)};
    assert(jm.dump() == "18446744073709551614" && jm.is_number_unsigned());
    json js = small_id{static_cast<small_id>(0xDEADBEEFu)};
    assert(js.dump() == "3735928559");
    json jn = neg_id{static_cast<neg_id>(-2)};
    assert(jn.dump() == "-2" && jn.is_number_integer());
    json jz = book_id{static_cast<book_id>(0)};
    assert(jz.dump() == "0");
    assert(j.get<book_id>() == book_id{static_cast<book_id>(static_cast<std::uint64_t>(1) << 63)});
    std::cout << "OK\n";
}
EOF
